// This code snippet demonstrates how to safely construct a URL with user ID validation
// and sanitization to prevent URL injection attacks.

import "strings"

func getURLForQuery(apiURL, userID string) *string {
	if userID == "" || strings.TrimSpace(userID) == "" {
		return nil
	}

	// Sanitize user ID by allowing only alphanumeric and hyphen characters
	if !strings.ContainsFunc(userID, func(c rune) bool {
		return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '-'
	}) {
		return nil
	}

	fullURL := apiURL + "/" + userID
	return &fullURL
}

